// ICE (STUN/TURN) server list for audio/video calls. The provider is chosen with TURN_PROVIDER:
//   none          STUN only (default, free, no account)
//   static        fixed TURN_URLS + TURN_USERNAME + TURN_CREDENTIAL
//   coturn-secret short-lived credentials signed with TURN_SHARED_SECRET (coturn use-auth-secret)
//   cloudflare    credentials generated by Cloudflare Realtime TURN
//   metered       credentials fetched from Metered (metered.ca)
// Secrets stay on the server. Credentials are cached briefly and are never logged.
const crypto = require('crypto');
const env = require('../config/env');

const STUN = [{ urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302'] }];
const CRED_TTL_S = 60 * 60; // coturn-secret / cloudflare credential lifetime: 1 hour
const MAX_CACHE_MS = 10 * 60 * 1000; // reuse generated credentials for at most 10 minutes
const FETCH_TIMEOUT_MS = 5000;

// Browsers refuse TURN/STUN on port 53, so drop any such URL a provider returns.
const usableUrl = (u) => typeof u === 'string' && /^(stun|stuns|turn|turns):/i.test(u) && !/:53(\?|$)/.test(u);

function clean(servers) {
  const out = [];
  for (const s of Array.isArray(servers) ? servers : [servers]) {
    if (!s || typeof s !== 'object') continue;
    const urls = (Array.isArray(s.urls) ? s.urls : [s.urls || s.url]).filter(usableUrl);
    if (!urls.length) continue;
    const entry = { urls };
    if (s.username) entry.username = String(s.username);
    if (s.credential) entry.credential = String(s.credential);
    out.push(entry);
  }
  return out;
}

const hasRelay = (servers) => servers.some((s) => s.urls.some((u) => /^turns?:/i.test(u)));

// coturn REST API scheme: username = "<expiry unix time>:<label>",
// credential = base64(HMAC-SHA1(shared secret, username)).
function coturnCredentials(secret, label, now = Date.now(), ttl = CRED_TTL_S) {
  const username = `${Math.floor(now / 1000) + ttl}:${label}`;
  const credential = crypto.createHmac('sha1', secret).update(username).digest('base64');
  return { username, credential };
}

async function fetchJson(url, options = {}) {
  const res = await fetch(url, { ...options, signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
  if (!res.ok) throw new Error(`TURN provider answered HTTP ${res.status}`);
  return res.json();
}

const providers = {
  none: async () => ({ servers: [], ttl: Infinity }),

  static: async (t) => ({ servers: clean({ urls: t.urls, username: t.username, credential: t.credential }), ttl: Infinity }),

  'coturn-secret': async (t) => {
    // An opaque label, not the user id: the TURN server never learns who is calling.
    const label = crypto.randomBytes(6).toString('hex');
    return { servers: clean({ urls: t.urls, ...coturnCredentials(t.sharedSecret, label) }), ttl: CRED_TTL_S };
  },

  cloudflare: async (t) => {
    const data = await fetchJson(`https://rtc.live.cloudflare.com/v1/turn/keys/${encodeURIComponent(t.cloudflareKeyId)}/credentials/generate`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${t.cloudflareToken}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ ttl: CRED_TTL_S }),
    });
    return { servers: clean(data.iceServers), ttl: CRED_TTL_S };
  },

  metered: async (t) => {
    const data = await fetchJson(
      `https://${encodeURIComponent(t.meteredAppName)}.metered.live/api/v1/turn/credentials?apiKey=${encodeURIComponent(t.meteredApiKey)}`
    );
    return { servers: clean(data), ttl: CRED_TTL_S };
  },
};

let cache = null; // { value, expiresAt }

// Returns { iceServers, provider, turn, ttl }. Never throws: falls back to STUN only.
async function getIceServers() {
  if (cache && cache.expiresAt > Date.now()) return cache.value;

  const { provider } = env.turn;
  let servers = [];
  let ttl = Infinity;
  let degraded = false;
  try {
    ({ servers, ttl } = await providers[provider](env.turn));
  } catch (err) {
    degraded = true;
    // Message only: never the request, URL (may contain a key) or response body.
    console.warn(`TURN (${provider}): could not get credentials, using STUN only. ${err.name === 'TimeoutError' ? 'Timed out' : err.message}`);
  }

  const iceServers = [...STUN, ...servers];
  const value = { iceServers, provider, turn: hasRelay(servers), ttl: Number.isFinite(ttl) ? ttl : null };
  // Cache good answers for up to half their lifetime; retry failures after 30 seconds.
  const keepMs = degraded ? 30_000 : Math.min(MAX_CACHE_MS, Number.isFinite(ttl) ? (ttl * 1000) / 2 : MAX_CACHE_MS);
  cache = { value, expiresAt: Date.now() + keepMs };
  return value;
}

module.exports = { getIceServers, coturnCredentials, clean, usableUrl, STUN };
